),
resolved_tracks AS (
    SELECT seed_tracks.*, artist.id AS artist_id, (
        SELECT track_id FROM track_provider
        WHERE provider = 'deezer'
          AND provider_track_id = seed_tracks.provider_track_id
    ) AS existing_track_id
    FROM seed_tracks
    LEFT JOIN artist
      ON artist.external_ids ->> 'musicbrainz' = seed_tracks.musicbrainz_artist_id
),
new_tracks AS (
    INSERT INTO track (id, artist_id)
    SELECT seed_track_id, artist_id
    FROM resolved_tracks
    WHERE existing_track_id IS NULL
    RETURNING id
),
target_tracks AS (
    SELECT resolved_tracks.*,
           coalesce(existing_track_id, new_tracks.id) AS track_id
    FROM resolved_tracks
    LEFT JOIN new_tracks ON new_tracks.id = resolved_tracks.seed_track_id
)
INSERT INTO track_provider (track_id, provider, provider_track_id, title, duration_ms)
SELECT track_id, 'deezer', provider_track_id, title, duration_ms
FROM target_tracks
ON CONFLICT (track_id, provider, provider_track_id) DO UPDATE
SET title = EXCLUDED.title,
    duration_ms = EXCLUDED.duration_ms;
